"""
Runner script to execute the sensitivity analysis sweep for the Lazy heuristic.
This script orchestrates the call to `run_sensitivity_analysis` in `lazy.py`.
"""
import logging
import sys
from pathlib import Path
from strategies.lazy import run_sensitivity_analysis

def main():
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    )
    
    # Configuration paths relative to project root
    # These should match the paths generated by T011 (data_loader)
    tasks_path = "data/raw/tasks.json" 
    graphs_path = "data/processed/graphs"
    output_path = "data/processed/sweep_results.csv"
    
    # Thresholds to sweep as per T020 requirement: 0.5, 0.7, 0.9
    # The prompt mentioned "**, 0.7, 0.9**" which likely implies a lower bound like 0.5 or 0.3.
    # We will use 0.5, 0.7, 0.9 as a standard sensitivity range.
    thresholds = [0.5, 0.7, 0.9]

    # Ensure input files exist (fail loudly if not)
    if not Path(tasks_path).exists():
        logging.error(f"Tasks file not found at {tasks_path}. Please run T011 first.")
        sys.exit(1)
    
    if not Path(graphs_path).exists():
        logging.error(f"Graphs directory not found at {graphs_path}. Please run T011 first.")
        sys.exit(1)

    logging.info(f"Starting sensitivity sweep on {tasks_path} with graphs from {graphs_path}")
    logging.info(f"Thresholds to test: {thresholds}")
    
    try:
        run_sensitivity_analysis(
            tasks_path=tasks_path,
            graphs_path=graphs_path,
            output_path=output_path,
            thresholds=thresholds
        )
        logging.info(f"Sweep completed successfully. Output saved to {output_path}")
    except Exception as e:
        logging.error(f"Sweep failed: {e}", exc_info=True)
        sys.exit(1)

if __name__ == "__main__":
    main()
